// The size of the controls of one row (rule D15). A `ControlRow` gives its controls one tier, and a control that has no `size` of its own takes it:
// a Button or an IconButton takes the tier as it is (xsm 32 · sm 40 · md 48 · lg 56); a field (TextField, Select, Autocomplete…) takes the field size of that height
// (the field sizes are 48 and 56, so only md and lg have a field). A size set on the control itself always wins.
import { createContext, useContext } from './react.js';

export const ControlSizeContext = createContext(/** @type {string | null} */ (null));
/** The tier of the row the control stands in, or null outside a ControlRow. */
export const useControlSize = () => useContext(ControlSizeContext);
/** The size of a field of a tier: the 48px field is `sm`, the 56px field is `md`. */
export const FIELD_OF_TIER = { md: 'sm', lg: 'md' };

// Documentation of the components: the description and the props table of each page. The usage (do and don't) is in src/usage.js and is read from there (usageOf), so apps do not carry it.
// props: { name: ['type', 'default' | null, 'description'] }

const docProps = (props) => Object.fromEntries(Object.entries(props).map(([name, [type, def, text]]) => [name, {
  required: false,
  tsType: { name: type, raw: type },
  ...(def != null && { defaultValue: { value: def, computed: false } }),
  description: text,
}]));

/** Attaches a description and its props to a component. */
export function describe(component, description, props) {
  component.__docgenInfo = { description, props: docProps(props) };
  return component;
}

/** Documents a component of the system that wraps a compiled one: the props of the compiled one, plus (or replaced by) its own. */
export function describeWrapper(component, base, props, description) {
  const doc = base.__docgenInfo || { description: '', props: {} };
  component.__docgenInfo = { ...doc, description: description ?? doc.description, props: { ...doc.props, ...docProps(props) } };
  return component;
}

// Panels (Dropdown, Popover) open over the page: they are drawn in <body> with fixed coordinates taken from their trigger,
// so no scrolling or clipping container around the trigger can cut them or push the layout. They flip to the other side
// when there is no room and stay inside the screen.
import { useState, useCallback, useEffect, useLayoutEffect, useRef } from './react.js';
import { createPortal } from 'react-dom';

const GAP = 8;
const EDGE = 8;

/** Draws `children` in <body>. */
export const Floating = ({ children }) => createPortal(children, document.body);

/**
 * Where the open panel goes: `{ top, left, width?, maxHeight, placement }` for position: fixed.
 * @param anchorRef  the element the panel hangs on (the trigger)
 * @param panelRef   the panel itself, measured after it is rendered
 * @param placement  'bottom-start' | 'bottom-end' | 'top-start' | 'top-end'; the opposite side is used when this one has no room, and the other alignment
 *                  (left edge or right edge of the anchor) when this one runs out of the window
 * @param matchWidth give the panel the width of the anchor
 */
export function useAnchoredPosition(open, anchorRef, panelRef, placement, matchWidth = false) {
  const [pos, setPos] = useState(null);
  const update = useCallback(() => {
    const anchor = anchorRef.current;
    const panel = panelRef.current;
    if (!anchor || !panel) return;
    const r = anchor.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const vh = window.innerHeight;
    const width = matchWidth ? r.width : panel.offsetWidth;
    const natural = panel.scrollHeight;
    const below = vh - r.bottom - GAP - EDGE;
    const above = r.top - GAP - EDGE;
    let side = placement.startsWith('top') ? 'top' : 'bottom';
    if (side === 'bottom' && natural > below && above > below) side = 'top';
    else if (side === 'top' && natural > above && below > above) side = 'bottom';
    const room = side === 'bottom' ? below : above;
    const height = Math.min(natural, room);
    // aligned to the left edge of the anchor by default (`start`), to its right edge when that does not fit (and the other way round for `end`);
    // never centered or shifted by a few pixels: only when neither fits is the panel kept inside the window
    const fitsStart = r.left + width <= vw - EDGE;
    const fitsEnd = r.right - width >= EDGE;
    let end = placement.endsWith('end');
    if (end && !fitsEnd && fitsStart) end = false;
    else if (!end && !fitsStart && fitsEnd) end = true;
    const left = Math.max(EDGE, Math.min(end ? r.right - width : r.left, vw - width - EDGE));
    const top = side === 'bottom' ? r.bottom + GAP : r.top - GAP - height;
    setPos((p) => {
      const next = { top: Math.round(top), left: Math.round(left), width: matchWidth ? Math.round(r.width) : undefined, maxHeight: Math.floor(room), placement: `${side}-${end ? 'end' : 'start'}` };
      return p && Object.keys(next).every((k) => p[k] === next[k]) ? p : next;
    });
  }, [anchorRef, panelRef, placement, matchWidth]);

  useLayoutEffect(() => {
    if (!open) { setPos(null); return undefined; }
    update();
    window.addEventListener('resize', update);
    window.addEventListener('scroll', update, true);
    const ro = typeof ResizeObserver === 'function' && panelRef.current ? new ResizeObserver(update) : null;
    ro?.observe(panelRef.current);
    return () => { window.removeEventListener('resize', update); window.removeEventListener('scroll', update, true); ro?.disconnect(); };
  }, [open, update]);
  return pos;
}

const OPPOSITE = { top: 'bottom', bottom: 'top', left: 'right', right: 'left' };

/**
 * Where a small bubble (a tooltip) goes: `{ top, left, side }` for position: fixed. It opens on `placement` (top, bottom, left or right of the
 * anchor), takes the opposite side when this one has not enough room in the window, and is kept inside the window along the other axis.
 */
export function useAnchoredSide(open, anchorRef, bubbleRef, placement = 'top') {
  const [pos, setPos] = useState(null);
  const update = useCallback(() => {
    const anchor = anchorRef.current;
    const bubble = bubbleRef.current;
    if (!anchor || !bubble) return;
    const r = anchor.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const vh = window.innerHeight;
    const w = bubble.offsetWidth;
    const h = bubble.offsetHeight;
    const room = { top: r.top - GAP - EDGE, bottom: vh - r.bottom - GAP - EDGE, left: r.left - GAP - EDGE, right: vw - r.right - GAP - EDGE };
    const need = placement === 'top' || placement === 'bottom' ? h : w;
    const side = room[placement] < need && room[OPPOSITE[placement]] > room[placement] ? OPPOSITE[placement] : placement;
    const across = (start, size, limit) => Math.max(EDGE, Math.min(start, limit - size - EDGE));
    let top;
    let left;
    if (side === 'top' || side === 'bottom') {
      top = side === 'top' ? r.top - GAP - h : r.bottom + GAP;
      left = across(r.left + r.width / 2 - w / 2, w, vw);
    } else {
      left = side === 'left' ? r.left - GAP - w : r.right + GAP;
      top = across(r.top + r.height / 2 - h / 2, h, vh);
    }
    setPos((p) => (p && p.top === Math.round(top) && p.left === Math.round(left) && p.side === side ? p : { top: Math.round(top), left: Math.round(left), side }));
  }, [anchorRef, bubbleRef, placement]);
  useLayoutEffect(() => {
    if (!open) { setPos(null); return undefined; }
    update();
    window.addEventListener('resize', update);
    window.addEventListener('scroll', update, true);
    return () => { window.removeEventListener('resize', update); window.removeEventListener('scroll', update, true); };
  }, [open, update]);
  return pos;
}

/** The inline style of a positioned panel; hidden for the one frame before it is measured. */
export const panelStyle = (pos) => (pos
  ? { position: 'fixed', top: pos.top, left: pos.left, width: pos.width, maxHeight: pos.maxHeight }
  : { position: 'fixed', top: 0, left: 0, visibility: 'hidden' });

/**
 * Closes an open panel the way every panel of the system closes: a press outside the trigger and the panel, or Escape
 * (focus then goes back to the trigger, the element with aria-haspopup inside the root).
 */
export function useDismiss(open, close, rootRef, panelRef) {
  const latest = useRef(close);
  latest.current = close;
  useEffect(() => {
    if (!open) return undefined;
    const outside = (e) => { if (!rootRef.current?.contains(e.target) && !panelRef.current?.contains(e.target)) latest.current(); };
    const escape = (e) => {
      if (e.key !== 'Escape' || e.defaultPrevented) return;
      e.preventDefault();
      latest.current();
      rootRef.current?.querySelector('[aria-haspopup]')?.focus();
    };
    document.addEventListener('pointerdown', outside);
    document.addEventListener('keydown', escape);
    return () => { document.removeEventListener('pointerdown', outside); document.removeEventListener('keydown', escape); };
  }, [open]);
}

// The sliding highlight of Tabs (underline), Segmented Control (thumb), Bottom Bar (pill) and OTP Input (focus ring):
// one element inside the container that moves to the active item. It is measured with layout offsets within the container,
// so a running animation or transform of an item (a shake, an entrance) never moves it, and it is measured again when the
// container changes size. The container must be positioned (position: relative).
import { useState, useRef, useLayoutEffect } from './react.js';

/** The position of `el` inside `container`, summed along the offset parents; null when `container` is not one of them. */
export function offsetWithin(el, container) {
  let x = 0, y = 0, e = el;
  while (e && e !== container) { x += e.offsetLeft; y += e.offsetTop; e = e.offsetParent; }
  return e === container ? { x, y } : null;
}

const same = (a, b) => a === b || (a && b && a.x === b.x && a.y === b.y && a.w === b.w && a.h === b.h && a.r === b.r);

/**
 * @param containerRef the positioned element the highlight lives in
 * @param find         (container) => the active item, or null
 * @param deps         what changes the active item or the layout
 * @param withRadius   also read the corner radius of the item (the highlight takes its shape)
 * @returns [rect | null, remeasure]   rect: { x, y, w, h, r? }
 */
export function useHighlight(containerRef, find, deps, { withRadius = false } = {}) {
  const [rect, setRect] = useState(null);
  const measure = useRef(() => {});
  measure.current = () => {
    const box = containerRef.current;
    const el = box && find(box);
    const at = el && offsetWithin(el, box);
    const next = at ? { ...at, w: el.offsetWidth, h: el.offsetHeight, ...(withRadius && { r: getComputedStyle(el).borderTopLeftRadius }) } : null;
    setRect((prev) => (same(prev, next) ? prev : next));
  };
  useLayoutEffect(() => {
    measure.current();
    const box = containerRef.current;
    if (!box) return undefined;
    const ro = new ResizeObserver(() => measure.current());
    ro.observe(box);
    return () => ro.disconnect();
  }, deps);
  return [rect, () => measure.current()];
}

// Icon weight: the stroke of an outline icon follows the thickness of the text it stands next to.
// A stem of the text is a fraction of the font size that grows with the font weight; the icon is drawn in a 24 box, so the stroke
// that matches the stem is the stem in px scaled by 24 / icon size. It is kept between MIN and MAX; a text that is bolder than MAX
// can take is matched by the filled icon instead.
import { useState, useLayoutEffect, useRef } from './react.js';

export const MIN_STROKE = 1;
export const MAX_STROKE = 2.5;
export const DEFAULT_STROKE = 2;
// stem thickness in em by font weight (a typical text face)
const STEM = [[100, 0.04], [200, 0.05], [300, 0.065], [400, 0.085], [500, 0.1], [600, 0.115], [700, 0.13], [800, 0.15], [900, 0.17]];
const stemEm = (weight) => {
  const w = Math.max(100, Math.min(900, weight));
  const i = STEM.findIndex(([x]) => x >= w);
  if (i <= 0) return STEM[0][1];
  const [x0, y0] = STEM[i - 1], [x1, y1] = STEM[i];
  return y0 + ((y1 - y0) * (w - x0)) / (x1 - x0);
};
const round = (n) => Math.round(n * 4) / 4;

/** The stroke (in a 24 box) that matches a text, and whether it is too thick for an outline icon. */
export function iconWeight({ fontSize, fontWeight, iconSize = 24 }) {
  const wanted = stemEm(fontWeight) * fontSize * (24 / iconSize);
  return { wanted, stroke: round(Math.max(MIN_STROKE, Math.min(MAX_STROKE, wanted))), filled: wanted > MAX_STROKE };
}

/** The text an icon is the companion of: the nearest text beside it in its group (up to three levels up). */
export function textNear(svg) {
  let node = svg;
  for (let level = 0; level < 3 && node.parentElement; level += 1) {
    const parent = node.parentElement;
    const text = [...parent.childNodes].find((n) => n !== node && !n.contains(svg) && !(n.nodeType === 1 && n.matches?.('svg')) && n.textContent.trim());
    if (text) return text.nodeType === 1 ? text : parent;
    node = parent;
  }
  return null;
}
export function weightNear(svg, iconSize) {
  const el = textNear(svg);
  if (!el) return null;
  const cs = getComputedStyle(el);
  return { ...iconWeight({ fontSize: parseFloat(cs.fontSize), fontWeight: parseInt(cs.fontWeight, 10) || 400, iconSize: iconSize ?? svg.getBoundingClientRect().width }), el };
}

/** A ref for the element that wraps the icon (its first child is the svg) and the weight that matches its text: { stroke, filled }; until it is measured the default stroke. */
export function useIconWeight(enabled, size, deps = []) {
  const ref = useRef(null);
  const [weight, setWeight] = useState({ stroke: DEFAULT_STROKE, filled: false });
  useLayoutEffect(() => {
    if (!enabled || !ref.current) return;
    const w = weightNear(ref.current.firstElementChild || ref.current, size);
    if (w && (w.stroke !== weight.stroke || w.filled !== weight.filled)) setWeight({ stroke: w.stroke, filled: w.filled });
  }, [enabled, size, ...deps]);
  return [ref, weight];
}

// Single access point for React and shared helpers of baseui components.
import * as ReactModule from 'react';

// react comes from the page: an import map in the documentation site, node_modules in an application (never a second copy)
const Interop = /** @type {any} */ (ReactModule);
export const React = Interop.default && Interop.default.createElement ? Interop.default : ReactModule;
export const h = React.createElement;
export const {
  Children, Fragment, cloneElement, createContext, forwardRef, isValidElement, memo, useCallback, useDeferredValue, useContext, useEffect, useId, useLayoutEffect, useMemo, useReducer, useRef, useState, useSyncExternalStore,
} = React;

/** Join class names: cx('a', cond && 'b') */
export const cx = (...parts) => parts.filter(Boolean).join(' ');

/**
 * Controlled / uncontrolled state: value + defaultValue + onChange.
 * Convention for all baseui components: `value`, `defaultValue`, `onValueChange`.
 */
export function useControllable(value, defaultValue, onChange) {
  const [inner, setInner] = useState(defaultValue);
  const controlled = value !== undefined;
  const current = controlled ? value : inner;
  const set = useCallback((next) => {
    if (!controlled) setInner(next);
    if (onChange) onChange(next);
  }, [controlled, onChange]);
  return [current, set];
}

// The theme settings that components follow, and the shared hooks around them.
//
// One convention for every setting: the theme writes it on <html> as a data attribute (data-motion, data-glass, data-floating),
// and a component that overrides it with a prop writes the same attribute on its own root, or on its floating panel:
//   motion   'off' | 'basic' | 'enhanced'  → data-motion   (CSS: --bui-fx is 1 only in enhanced; off stops transitions and animations)
//   glass    true | false | 'dropdowns'    → data-glass="on" | "off" | "dropdowns" (the theme can ask for the glass of dropdown menus only; a component's prop is only true or false)
//   floating true | false                  → the floating layout of the bars and the dialog (a class of the component; read with useFloating)
import { React, useState, useEffect, useRef, useCallback } from './react.js';

/** The value of a data attribute of <html>, kept up to date when the theme changes. */
export function useRootAttr(name) {
  const read = () => document.documentElement.getAttribute(`data-${name}`);
  const [value, setValue] = useState(read);
  useEffect(() => {
    const ob = new MutationObserver(() => setValue(read()));
    ob.observe(document.documentElement, { attributes: true, attributeFilter: [`data-${name}`] });
    setValue(read());
    return () => ob.disconnect();
  }, [name]);
  return value;
}

/** The motion level of one component: its own prop, else the theme setting; basic when nothing sets it. */
export const useMotion = (motion) => { const root = useRootAttr('motion'); return motion || root || 'basic'; };
/** The floating layout of one component: its own prop, else the theme setting. */
export const useFloating = (floating) => { const root = useRootAttr('floating') === 'on'; return floating ?? root; };
/** The motion level that applies to an element: the nearest data-motion around it (its component or the page). */
export const motionOf = (el) => el?.closest?.('[data-motion]')?.dataset.motion || 'basic';

/** The data attributes of the per-component overrides, written the way the theme writes them on <html>. */
export const themeAttrs = ({ motion, glass } = /** @type {{ motion?: string, glass?: boolean | string }} */ ({})) => ({
  'data-motion': motion || undefined,
  'data-glass': glass === true ? 'on' : glass === false ? 'off' : undefined,
});

/** A media query, kept up to date. */
export function useMediaQuery(query) {
  const subscribe = useCallback((cb) => {
    const q = window.matchMedia(query);
    q.addEventListener('change', cb);
    return () => q.removeEventListener('change', cb);
  }, [query]);
  return React.useSyncExternalStore(subscribe, () => window.matchMedia(query).matches, () => false);
}
/** A touch screen: no hover there, so hover-only UI (tooltips) stays hidden and hover styles must not stick. */
export const useTouchScreen = () => useMediaQuery('(hover: none), (pointer: coarse)');

/** False on the first frame, true afterwards: transitions switched on with it do not play from the initial position. */
export function useReady() {
  const [ready, setReady] = useState(false);
  useEffect(() => { const id = requestAnimationFrame(() => setReady(true)); return () => cancelAnimationFrame(id); }, []);
  return ready;
}

/** Basic animations: the highlight (underline, thumb, pill) does not slide, it appears at the new place with a short fade. */
export function useAppear(ref, container, key) {
  const first = useRef(true);
  useEffect(() => {
    if (first.current) { first.current = false; return; }
    const el = ref.current;
    if (el && el.animate && motionOf(container.current) === 'basic') el.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 150, easing: 'ease-out' });
  }, [key]);
}

/** Keeps a panel mounted for `ms` after it closes so it can play an exit animation; returns [mounted, closing]. */
export function usePresence(open, ms) {
  const [mounted, setMounted] = useState(open);
  useEffect(() => {
    if (open) { setMounted(true); return undefined; }
    if (!ms) { setMounted(false); return undefined; }
    const t = setTimeout(() => setMounted(false), ms);
    return () => clearTimeout(t);
  }, [open, ms]);
  if (!ms) return [open, false];
  return [open || mounted, !open && mounted];
}

// Usage guidance per component: what to do and what not to do. It is attached to the component by describe() (src/doc.js),
// shown as the Usage block of its page, and written to docs/components/<name>.md, where an agent reads it before it builds.
// Keys are the names of the exported components. Rules that hold for the whole interface are in the constitution (rules.js);
// these are the choices inside one component: when to reach for it, and what goes wrong.
// Shaped by the usage guidelines of Astryx, reworded for the components and API of baseui; guidance that depends on
// Astryx-only parts (StyleX, xstyle, disabledMessage, Drawer, Stepper) is left out.

export const USAGE = {
  // ------------------------------------------------------------------ actions
  ButtonGroup: {
    do: [
      'Put the buttons of one decision in a ButtonGroup; let the group, not the buttons, decide the width',
      'Use `orientation="vertical"` when the buttons are stacked: they fill the width of the group',
      'In a vertical group put the primary action first; use `stackOnMobile` for a footer that is a row on a desktop and a column on a phone',
    ],
    dont: [
      'Set `width="100%"` on each button of a stack by hand: the group does it',
      'Put two primary buttons in one group: one primary, the rest secondary or ghost',
      'Use it for unrelated buttons or for a toolbar of icon buttons: use ControlRow',
    ],
  },
  Form: {
    do: [
      'Lay a form out with Form: one gap between rows and between columns, so the distance is the same in both directions',
      'Put fields that belong together in a FormRow (city and country, expiry and CVC); use a ratio such as [2, 1] for a long field and a short one',
      'Group a long form in FormSections with a heading; the sections stand at the group distance, and when a form has sections everything in it is in a section (a section without a title is fine)',
      'Put a switch or a checkbox beside a field in a FormRow with `align="center"`; a button beside a field takes the height of the fields by itself',
    ],
    dont: [
      'Space the fields of one form with different gaps, or give a field a margin (D18)',
      'Put more than four fields in a row, or fields of very different heights side by side',
      'Build the rows with a Stack and a Grid of your own: the gaps drift apart',
    ],
  },
  Button: {
    do: [
      'Give one primary button to the most important action of a view; use secondary or ghost for the rest',
      'Label it with the action: "Save changes", "Delete account", "Send invite"',
      'Show progress for an action that takes time: `loading`, or `clickAction` for an async handler',
      'Use IconButton for a button with only an icon',
      'Beside an input, take the height and the text size of the input: size lg and textSize 16 for a 56px input, size md and textSize 14 for a 48px one',
    ],
    dont: [
      'Put more than one primary button in the same view',
      'Use the destructive variant for something irreversible without a confirmation step (AlertDialog)',
      'Use a button to go to another page: pass `href`, or use Link. Buttons act, links navigate',
      'Label it "OK", "Submit" or "Click here"',
    ],
  },
  IconButton: {
    do: [
      'Give it a specific `label` ("Delete conversation", not "Delete"): it is the accessible name and the tooltip',
      'Use the ghost variant in toolbars and dense areas',
      'Keep the tooltip on, so that sighted people get the hint a screen reader gets from the label',
    ],
    dont: [
      'Use it when the icon alone does not say what happens: use Button with text',
      'Turn the tooltip off for an icon that has no text beside it',
    ],
  },
  Link: {
    do: ['Write link text that says where it goes', 'Use it for navigation, inside text or on its own', 'Keep the default: the color of the text and an underline'],
    dont: ['Use a link for an action that does not navigate: use Button', 'Write "click here" or "read more"', 'Recolor a link in text or take its underline away'],
  },

  // ------------------------------------------------------------------ containers
  Card: {
    do: [
      'Ask "could I reorder or remove this on its own?": if yes it is a card (one profile, one notification, one metric, one product)',
      'Try removing the card first: spacing and type often group things well enough',
      'Keep padding the same across sibling cards so they line up in a grid',
      'Truncate long ids and urls inside a card instead of letting them stretch it',
    ],
    dont: [
      'Use cards as the default way to group things, or wrap page sections ("General settings", a form group) in them: use Section or a heading with a Stack',
      'Nest a card in a card',
      'Repeat identical cards of icon, heading and text: vary the layout, or ask whether cards are needed',
      'Use a card color variant to show status: use Banner or Badge',
    ],
  },
  ClickableCard: {
    do: ['Give the card one action (`href` or `onClick`) and a `label` that names it', 'Make the whole card the target'],
    dont: ['Put buttons or links inside a clickable card: two competing click targets'],
  },
  SelectableCard: {
    do: ['Use it to choose from a few rich options, like plans, with a clear selected state', 'Name the group for what is being chosen'],
    dont: ['Use it for a long list of choices: use a list with Checkbox or Radio', 'Put interactive elements inside it'],
  },
  Section: {
    do: ['Use it for a region of a page: a settings panel, a form group, a sidebar part', 'Pair it with a heading and a Stack'],
    dont: ['Use a Card when you mean a page region'],
  },
  ProductCard: {
    do: ['Use it for a compact product summary: a picture, the price, a title of two lines, the rating and one line of meta', 'Give the heart through `favorite` when the product can be kept', 'Put it inside a ProductListing, which lays the cards in rows'],
    dont: ['Use it when the content needs a different structure than this compact card supports', 'Add more lines to it (a description, three badges): a listing is scanned, not read'],
  },
  ProductListing: {
    do: ['Let the cards take the whole width of a row: the columns reflow and the listing always shows whole rows', 'Choose `more="button"`, `more="infinite"` or `more="pagination"` for the navigation the product needs', 'Set `hasMore`, `onLoadMore` and `loading` when the products come from a server'],
    dont: ['Leave a gap at the end of a row, or end a loaded part in the middle of a row', 'Mix loading and pagination state from different data sources'],
  },
  Group: { do: ['Use it for a heading with its content: the heading sits tight (8px) to what it names', 'Put the content in one block and let the Stack around the groups set the distance between them'], dont: ['Space a heading from its content as far as from the block above', 'Pull a block closer with a negative margin: put it in the same Group'] },
  Bleed: { do: ['Use it for a row of tags, a scroller or a listing that must reach the screen edges', 'Keep the first item on the edge of the text: the padding stays inside', 'Use `outset` when only a card background should reach out and the picture keeps the edge'], dont: ['Write a negative margin for it by hand', 'Use it for text, which must keep its margin'] },
  Stack: {
